def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    last_me = me[-1]
    last_opp = opp[-1]

    opp_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1

    my_d = 0
    for x in me:
        if x == 'D':
            my_d += 1

    recent = opp[-8:] if n >= 8 else opp
    recent_len = len(recent)
    recent_d = 0
    for x in recent:
        if x == 'D':
            recent_d += 1

    recent_def = recent_len >= 4 and recent_d * 2 >= recent_len
    recent_all_d = recent_len >= 2 and recent_d == recent_len

    recent6 = opp[-6:] if n >= 6 else opp
    recent6_d = 0
    for x in recent6:
        if x == 'D':
            recent6_d += 1

    cons_d = 0
    for x in reversed(opp):
        if x == 'D':
            cons_d += 1
        else:
            break

    cons_c = 0
    for x in reversed(opp):
        if x == 'C':
            cons_c += 1
        else:
            break

    after_d_total = 0
    after_d_d = 0
    for i in range(n - 1):
        if me[i] == 'D':
            after_d_total += 1
            if opp[i + 1] == 'D':
                after_d_d += 1

    alt_changes = 0
    for i in range(1, n):
        if opp[i] != opp[i - 1]:
            alt_changes += 1

    alt_high = (
        n >= 12 and
        alt_changes * 10 >= 7 * (n - 1) and
        my_d * 5 <= n and
        opp_d * 2 <= n
    )

    mostly_d = opp_d >= 6 and opp_d * 2 > n

    if n >= 99:
        return 'D'

    if n == 98:
        if alt_high or mostly_d or recent_def or recent_all_d or last_opp == 'D':
            return 'D'
        if opp_d <= 2 and after_d_total >= 1 and after_d_d == 0:
            return 'D'
        return 'C'

    if opp_d == n and n >= 2:
        return 'D'

    if alt_high:
        return 'D'

    if recent_all_d:
        return 'D'

    if mostly_d or recent_def:
        if last_opp == 'C':
            if cons_c >= 2 and opp_d * 3 <= n:
                return 'C'
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    if (
        opp_d <= 2 and
        after_d_total >= 1 and
        after_d_d == 0 and
        last_opp == 'C' and
        recent6_d <= 1
    ):
        return 'D'

    if n == 45 and opp_d == 0 and my_d == 0 and recent_d == 0:
        if rng.random() < 0.18:
            return 'D'

    if last_opp == 'D':
        if cons_d >= 3:
            return 'D'

        if cons_d >= 2 and cons_d == opp_d:
            return 'D'

        if opp_d <= 3 and recent6_d <= 2:
            if last_me == 'D':
                return 'C'

            # If this defection is likely a delayed retaliation to our previous
            # defection, forgive instead of prolonging an alternating punishment.
            if n >= 2 and me[-2] == 'D' and cons_d == 1:
                return 'C'

            if cons_d == 1:
                return 'D'

            return 'C'

        if rng.random() < 0.25:
            return 'C'

        return 'D'

    return 'C'
